const $=(s,r=document)=>r.querySelector(s);
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const app=$("#admin-app");
const labels={home:"全站圖文設定",places:"地圖地點",articles:"文章故事",routes:"主題路線",submissions:"投稿審核",reviews:"訪客評價"};
const state={authed:false,needsSetup:false,tab:"home",edit:null,records:{places:[],articles:[],routes:[],submissions:[]},site:{},maptilerKey:"",routeIds:[],filters:{places:{query:"",category:"全部",status:"全部"},articles:{query:"",category:"全部",status:"全部"},routes:{query:"",category:"全部",status:"全部"},submissions:{query:"",status:"全部"},reviews:{query:"",status:"全部"}}};
let pickerMap,pickerMarker;
async function api(url,options={}){const r=await fetch(url,options),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||"操作失敗");return d}
function toast(m){let e=$(".toast");if(!e){e=document.createElement("div");e.className="toast";document.body.append(e)}e.textContent=m;e.classList.add("show");setTimeout(()=>e.classList.remove("show"),2200)}
function field(n,l,v="",a=""){return '<label class="field">'+l+'<input name="'+n+'" value="'+esc(v)+'" '+a+'></label>'}
function area(n,l,v="",rows=4){return '<label class="field">'+l+'<textarea name="'+n+'" rows="'+rows+'">'+esc(v)+'</textarea></label>'}
function select(n,l,values,current="",cls=""){return '<label class="field '+cls+'">'+l+'<select name="'+n+'">'+values.map(v=>{const x=Array.isArray(v)?v:[v,v];return '<option value="'+esc(x[0])+'" '+(x[0]===current?"selected":"")+'>'+esc(x[1])+'</option>'}).join("")+"</select></label>"}
function imageField(n,l,v="",allowClear=false){return '<div class="field image-field"><strong>'+l+'</strong><img class="image-preview" data-preview="'+n+'" src="'+esc(v||"assets/macau-waterfront.png")+'" alt="" '+(v?"":"style=\"opacity:.35\"")+"><input name=\""+n+'" value="'+esc(v)+'" readonly><div style="display:flex;gap:8px;flex-wrap:wrap"><label class="btn btn-muted">上傳圖片<input type="file" accept="image/png,image/jpeg,image/webp" data-upload="'+n+'" hidden></label>'+(allowClear?'<button type="button" class="btn btn-outline" data-clear-image="'+n+'">清除圖片</button>':"")+"</div><small>JPG、PNG 或 WebP，最多 5 MB。</small></div>"}
function pair(a,b){return '<div class="locale-pair"><section><h3>繁體中文</h3>'+a+'</section><section><h3>English</h3>'+b+"</section></div>"}
function login(){return '<main class="login-shell"><section class="login-card"><div class="brand"><img src="assets/grg-logo.png" alt=""><span>綠門GO</span></div><h1>'+(state.needsSetup?"建立管理員密碼":"登入內容後台")+'</h1><p>'+(state.needsSetup?"本地首次使用，請設定至少 12 個字元的密碼。":"管理首頁、地點、文章、路線及投稿。")+'</p><form id="auth-form">'+field("password","密碼","","type=\"password\" minlength=\"12\" required")+(state.needsSetup?field("confirm","確認密碼","","type=\"password\" minlength=\"12\" required"):"")+'<div id="auth-error"></div><button class="btn btn-primary">'+(state.needsSetup?"建立並登入":"登入")+"</button></form></section></main>"}
function shell(c){return '<div class="shell"><aside class="sidebar"><div class="brand"><img src="assets/grg-logo.png" alt=""><span>綠門GO 管理台</span></div><nav class="nav">'+Object.entries(labels).map(([k,v])=>'<button data-tab="'+k+'" class="'+(state.tab===k?"active":"")+'">'+v+"</button>").join("")+'</nav><div class="sidebar-bottom"><a href="/" target="_blank">開啟前台 ↗</a><button class="btn" data-action="logout">登出</button></div></aside><main class="main">'+c+"</main></div>"}
function head(s="管理前台顯示內容"){return '<header class="main-head"><div><small>GREEN GATEWAY CMS</small><h1>'+labels[state.tab]+"</h1><p>"+s+"</p></div>"+(!["home","submissions","reviews"].includes(state.tab)&&!state.edit?'<button class="btn btn-primary" data-action="new">＋ 新增</button>':"")+"</header>"}
function articleSelect(n,l,current){return select(n,l,[["","不連結文章"],...state.records.articles.map(a=>[a.id,a.title])],current)}
const catKeys=[["食","食 (Eat)"],["買","買 (Shop)"],["修","修 (Repair)"],["去","去 (Explore)"],["學","學 (Learn)"],["參與","參與 (Join)"]];
