 const s=state.site,c=s.categories||[],exps=s.experiences||[];
 let cards=c.map((x,i)=>'<fieldset data-cat-item="'+i+'"><legend>分類卡片 '+(i+1)+'<button type="button" class="btn btn-danger" style="margin-left:10px;min-height:28px;padding:4px 10px;font-size:12px" data-remove-cat="'+i+'">刪除</button></legend>'+select("categoryKey"+i,"對應地圖分類",catKeys,x.key)+pair(field("categoryTitleZh"+i,"標題",x.titleZh)+field("categorySubZh"+i,"副標題",x.subtitleZh),field("categoryTitleEn"+i,"Title",x.titleEn)+field("categorySubEn"+i,"Subtitle",x.subtitleEn))+imageField("categoryImage"+i,"卡片配圖",x.image)+"</fieldset>").join("");
 let expCards=exps.map((x,i)=>'<fieldset data-exp-item="'+i+'"><legend>用戶體驗 '+(i+1)+'<button type="button" class="btn btn-danger" style="margin-left:10px;min-height:28px;padding:4px 10px;font-size:12px" data-remove-exp="'+i+'">刪除</button></legend>'+field("expAuthor"+i,"留言 ID / 作者",x.author)+pair(area("expTextZh"+i,"中文評價",x.textZh,3),area("expTextEn"+i,"English review",x.textEn,3))+imageField("expImage"+i,"配圖（選填，留空則不顯示圖片）",x.image,true)+"</fieldset>").join("");
 return head("統一管理網站所有區塊的配圖、中英文文案與分類內容，儲存後前台即時生效。")+'<form id="site-form" class="site-editor">'
 +'<section class="panel"><h2>首屏 Hero 與主視覺</h2>'+pair(area("heroTitleZh","主標題",s.heroTitleZh,3)+area("heroBodyZh","簡介文字",s.heroBodyZh,3),area("heroTitleEn","Heading",s.heroTitleEn,3)+area("heroBodyEn","Intro text",s.heroBodyEn,3))+pair(field("searchPlaceholderZh","搜尋框提示",s.searchPlaceholderZh)+field("hotSearchesZh","熱門搜尋（逗號分隔）",(s.hotSearchesZh||[]).join("，")),field("searchPlaceholderEn","Search placeholder",s.searchPlaceholderEn)+field("hotSearchesEn","Popular searches",(s.hotSearchesEn||[]).join(", ")))+'<div class="two-col">'+imageField("heroImage","首屏主圖片",s.heroImage)+articleSelect("heroArticleId","點擊主圖片連結至",s.heroArticleId)+'</div><h3 style="margin:24px 0 12px;font-size:15px;color:#123e31">首屏右側精選故事小卡</h3>'+pair(field("featureTitleZh","小卡標題",s.featureTitleZh),field("featureTitleEn","Card title",s.featureTitleEn))+'<div class="two-col">'+imageField("featureImage","小卡配圖",s.featureImage)+articleSelect("featureArticleId","點擊小卡連結至",s.featureArticleId)+'</div></section>'
 +'<section class="panel"><h2>分類探索區塊（可自由增減）</h2>'+pair(field("catsTitleZh","區塊標題",s.catsTitleZh)+area("catsBodyZh","區塊簡介",s.catsBodyZh,2),field("catsTitleEn","Section title",s.catsTitleEn)+area("catsBodyEn","Section intro",s.catsBodyEn,2))+'<div class="category-admin">'+cards+'</div><div style="margin-top:16px"><button type="button" class="btn btn-muted" data-action="add-cat">＋ 新增分類卡片</button></div></section>'
 +'<section class="panel"><h2>主題路線區塊</h2>'+pair(field("routesTitleZh","首頁路線標題",s.routesTitleZh)+area("routesBodyZh","首頁路線簡介",s.routesBodyZh,2),field("routesTitleEn","Routes title",s.routesTitleEn)+area("routesBodyEn","Routes intro",s.routesBodyEn,2))+'</section>'
