 +'<section class="panel"><h2>頁尾文案</h2>'+pair(field("footerTaglineZh","頁尾介紹",s.footerTaglineZh)+field("footerNoteZh","頁尾標語",s.footerNoteZh),field("footerTaglineEn","Footer intro",s.footerTaglineEn)+field("footerNoteEn","Footer tagline",s.footerNoteEn))+'</section>'
 +'<div class="form-footer"><button class="btn btn-primary">儲存全站設定</button></div></form>';
