function recordName(r){return r.name||r.title||r.n||"未命名"}
function list(){const all=state.records[state.tab]||[],f=state.filters[state.tab]||{query:"",category:"全部",status:"全部"},categories=[...new Set(all.map(r=>r.cat||r.category||"").filter(Boolean))].sort((a,b)=>a.localeCompare(b,"zh-Hant")),q=f.query.trim().toLowerCase(),rows=all.filter(r=>(f.category==="全部"||(r.cat||r.category||"")===f.category)&&(f.status==="全部"||r.status===f.status)&&(!q||[recordName(r),r.en,r.title_en,r.n_en,r.cat,r.category,r.category_en,r.cat_en].join(" ").toLowerCase().includes(q)));return head()+'<section class="list-controls" aria-label="內容篩選"><div class="toolbar"><label class="filter-search"><span>搜尋</span><input type="search" data-list-filter="query" value="'+esc(f.query)+'" placeholder="搜尋中文或英文名稱"></label><label><span>分類</span><select data-list-filter="category"><option value="全部">全部分類</option>'+categories.map(c=>'<option value="'+esc(c)+'" '+(f.category===c?"selected":"")+'>'+esc(c)+'</option>').join("")+'</select></label><label><span>發布狀態</span><select data-list-filter="status"><option value="全部" '+(f.status==="全部"?"selected":"")+'>全部狀態</option><option value="published" '+(f.status==="published"?"selected":"")+'>已發布</option><option value="draft" '+(f.status==="draft"?"selected":"")+'>草稿</option></select></label></div><p class="list-count">目前顯示 <strong>'+rows.length+'</strong> 筆，共 <strong>'+all.length+'</strong> 筆</p></section><div class="table-wrap"><table class="table"><thead><tr><th>名稱</th><th>狀態／分類</th><th>更新時間</th><th></th></tr></thead><tbody>'+rows.map(r=>'<tr><td><strong>'+esc(recordName(r))+'</strong><small>'+esc(r.en||r.title_en||r.n_en||"尚未填英文")+'</small></td><td><span class="badge '+esc(r.status)+'">'+(r.status==="published"?"已發布":"草稿")+"</span> "+esc(r.cat||r.category||"")+"</td><td>"+esc(r.updated_at?.slice(0,10)||"")+'</td><td class="row-actions"><button class="btn btn-muted" data-edit="'+esc(r.id)+'">編輯</button><button class="btn btn-danger" data-delete="'+esc(r.id)+'">刪除</button></td></tr>').join("")+"</tbody></table>"+(rows.length?"":'<div class="empty">沒有符合目前篩選條件的資料。</div>')+"</div>"}
const statusField=r=>select("status","發布狀態",[["draft","草稿"],["published","發布"]],r.status||"draft");
function placeEditor(r){const tags=["食物","減廢","水","自然與生物多樣性","社區","文化","青年","交通","重用"];return head()+'<form id="record-form" class="editor"><div class="panel"><h2>地點內容</h2><p class="helper">地圖右側資訊卡會同步使用此處的地點圖片、中英文名稱、地址、簡介與生活入口分類。</p>'+pair(field("name","中文名稱",r.name,"required"),field("en","English name",r.en))+pair(field("address","中文地址",r.address),field("address_en","English address",r.address_en))+'<div class="form-grid">'+select("cat","生活入口",["食","買","修","去","學","參與"],r.cat||"去")+select("area","地區",[["","未提供"],"澳門半島","氹仔","路環"],r.area||"")+"</div>"+pair(area("desc","中文簡介",r.desc),area("desc_en","English summary",r.desc_en))+pair(area("story","中文故事",r.story,9),area("story_en","English story",r.story_en,9))+pair(field("hours","中文營業時間",r.hours),field("hours_en","English opening hours",r.hours_en))+field("phone","電話",r.phone)+area("website","網站連結（每行一個）",r.website,3)+'<div class="field"><strong>生態標籤</strong><div class="tag-grid">'+tags.map(t=>'<label><input type="checkbox" name="tags" value="'+t+'" '+(r.tags?.includes(t)?"checked":"")+'><span>'+t+"</span></label>").join("")+'</div></div><div class="field"><strong>地圖標點</strong><p class="helper">未確認位置時，可將經緯度留空，地點只會顯示於列表。</p><button type="button" class="btn btn-muted" data-action="geocode">依中文地址搜尋座標</button><div id="map-picker" class="map-picker"></div><div class="form-grid">'+field("lat","緯度",r.lat??"",'type="number" step="any"')+field("lng","經度",r.lng??"",'type="number" step="any"')+"</div></div></div><aside class=\"side-panel\">"+imageField("img","地點圖片",r.img)+statusField(r)+'</aside><div class="form-footer"><button type="button" class="btn btn-outline" data-action="cancel">取消</button><button class="btn btn-primary">儲存地點</button></div></form>'}
function articleEditor(r){return head()+'<form id="record-form" class="editor"><div class="panel"><h2>文章內容</h2>'+pair(field("title","中文標題",r.title,"required"),field("title_en","English title",r.title_en))+pair(field("subtitle","中文摘要",r.subtitle),field("subtitle_en","English summary",r.subtitle_en))+pair(field("category","中文分類",r.category),field("category_en","English category",r.category_en))+pair(area("body","中文正文",r.body,18),area("body_en","English article",r.body_en,18))+select("place_id","關聯地點",[["","不關聯"],...state.records.places.map(p=>[p.id,p.name])],r.place_id)+'</div><aside class="side-panel">'+imageField("img","文章封面",r.img)+statusField(r)+'</aside><div class="form-footer"><button type="button" class="btn btn-outline" data-action="cancel">取消</button><button class="btn btn-primary">儲存文章</button></div></form>'}
function routeStops(){return state.routeIds.map((id,i)=>{const p=state.records.places.find(x=>x.id===id);return '<div class="route-stop"><b>'+(i+1)+"</b><span>"+esc(p?.name||id)+'</span><button type="button" data-move="'+i+'" data-dir="-1">↑</button><button type="button" data-move="'+i+'" data-dir="1">↓</button><button type="button" data-remove="'+i+'">×</button></div>'}).join("")||'<p class="helper">尚未選擇地點。</p>'}
function routeEditor(r){return head()+'<form id="record-form" class="editor"><div class="panel"><h2>路線內容</h2>'+pair(field("n","中文路線名稱",r.n,"required"),field("n_en","English route name",r.n_en))+pair(field("cat","中文分類",r.cat),field("cat_en","English category",r.cat_en))+pair(area("text","中文介紹",r.text,5),area("text_en","English description",r.text_en,5))+pair(field("time","中文預計時間",r.time),field("time_en","English duration",r.time_en))+'<div class="field"><strong>沿途地點</strong><div id="route-stops">'+routeStops()+'</div><select id="route-add"><option value="">＋ 加入地點</option>'+state.records.places.filter(p=>!state.routeIds.includes(p.id)).map(p=>'<option value="'+p.id+'">'+esc(p.name)+"</option>").join("")+'</select></div></div><aside class="side-panel">'+imageField("img","路線圖片",r.img)+statusField(r)+'</aside><div class="form-footer"><button type="button" class="btn btn-outline" data-action="cancel">取消</button><button class="btn btn-primary">儲存路線</button></div></form>'}
function submissions(onlyReviews=false){
 const all=state.records.submissions.filter(s=>onlyReviews?s.type==="評價":s.type!=="評價"),f=state.filters[onlyReviews?"reviews":"submissions"],q=f.query.trim().toLowerCase();
 const statusNames={pending:"待審核",approved:"已採納",rejected:"不採納"},counts={全部:all.length,pending:0,approved:0,rejected:0};
 all.forEach(s=>counts[s.status]=(counts[s.status]||0)+1);
 const rows=all.filter(s=>(f.status==="全部"||s.status===f.status)&&(!q||[s.name,s.type,s.area,s.address,s.description,s.contact,...(s.tags||[])].join(" ").toLowerCase().includes(q)));
 const filters=[["全部","全部"],["pending","待審核"],["approved","已採納"],["rejected","不採納"]].map(([value,label])=>`<button class="status-filter ${f.status===value?"active":""}" data-submission-filter="${value}"><span>${label}</span><strong>${counts[value]}</strong></button>`).join("");
 const cards=rows.map(s=>`<article class="submission-card"><div class="submission-card-head"><div><small>${onlyReviews?"留言 ID":"類型："+esc(s.type)} · ${esc(s.created_at?.slice(0,10))}</small><h3>${esc(s.name)}</h3></div><span class="badge ${esc(s.status)}">${statusNames[s.status]||esc(s.status)}</span></div>${!onlyReviews?`<p class="submission-meta">${esc([s.area,s.address].filter(Boolean).join(" · "))}</p>`:""}${s.tags?.length?`<div class="submission-tags">${s.tags.map(t=>`<span>${esc(t)}</span>`).join("")}</div>`:""}<p>${esc(s.description)}</p>${s.image?`<div class="submission-image"><a href="${esc(s.image)}" target="_blank" rel="noopener" title="點擊查看原圖"><img src="${esc(s.image)}" alt="${esc(s.name)}的圖片"></a><div><a class="btn btn-muted" href="${esc(s.image)}" target="_blank" rel="noopener">查看原圖 ↗</a><a class="btn btn-outline" href="${esc(s.image)}" download>下載原圖</a></div></div>`:""}<div class="submission-actions"><button class="btn btn-primary" data-submission-status="approved" data-submission-id="${esc(s.id)}" ${s.status==="approved"?"disabled":""}>✓ ${onlyReviews?"標示已讀／採納":"採納"}</button><button class="btn btn-danger" data-submission-status="rejected" data-submission-id="${esc(s.id)}" ${s.status==="rejected"?"disabled":""}>${onlyReviews?"封存":"不採納"}</button></div></article>`).join("");
 return head(onlyReviews?"查看訪客從前台「投稿／評價」送出的留言 ID、評價正文與圖片。":"審核公開投稿，採納後可再依資料建立地點或文章。")+`<section class="submission-controls"><div class="submission-status-filters">${filters}</div><div class="toolbar"><label class="filter-search"><span>${onlyReviews?"搜尋評價":"搜尋投稿"}</span><input type="search" data-list-filter="query" value="${esc(f.query)}" placeholder="${onlyReviews?"搜尋留言 ID 或評價內容":"搜尋名稱、地址、標籤或內容"}"></label></div><p class="list-count">目前顯示 <strong>${rows.length}</strong> 筆，共 <strong>${all.length}</strong> 筆</p></section>`+(cards||`<div class="empty">${onlyReviews?"目前還沒有訪客評價。":"沒有符合目前篩選條件的投稿。"}</div>`)
}
function render(){if(!state.authed){app.innerHTML=login();return}let c=state.tab==="home"?homeEditor():state.tab==="submissions"?submissions(false):state.tab==="reviews"?submissions(true):state.edit?(state.tab==="places"?placeEditor(state.edit):state.tab==="articles"?articleEditor(state.edit):routeEditor(state.edit)):list();app.innerHTML=shell(c);if(state.edit&&state.tab==="places")setTimeout(initPicker)}
async function refresh(){const [places,articles,routes,submissions,site]=await Promise.all([...["places","articles","routes","submissions"].map(k=>api("/api/admin/"+k)),api("/api/admin/site")]);state.records={places,articles,routes,submissions};state.site=site;render()}
async function init(){const [me,c]=await Promise.all([api("/api/admin/me"),api("/api/config")]);state.authed=me.authenticated;state.needsSetup=me.needsSetup;state.maptilerKey=c.maptilerKey||"";if(state.authed)await refresh();else render()}
function closePicker(){if(pickerMap){pickerMap.remove();pickerMap=null;pickerMarker=null}}
function initPicker(){const el=$("#map-picker");if(!el||!window.L)return;const lat=Number($('[name="lat"]').value)||22.1987,lng=Number($('[name="lng"]').value)||113.5439;pickerMap=L.map(el).setView([lat,lng],15);L.tileLayer(state.maptilerKey?"https://api.maptiler.com/maps/streets-v2/{z}/{x}/{y}.png?key="+encodeURIComponent(state.maptilerKey):"https://tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19}).addTo(pickerMap);pickerMarker=L.marker([lat,lng],{draggable:true});if($('[name="lat"]').value&&$('[name="lng"]').value)pickerMarker.addTo(pickerMap);const sync=x=>{$('[name="lat"]').value=x.lat.toFixed(6);$('[name="lng"]').value=x.lng.toFixed(6);pickerMarker.setLatLng(x).addTo(pickerMap)};pickerMap.on("click",e=>sync(e.latlng));pickerMarker.on("dragend",()=>sync(pickerMarker.getLatLng()))}
async function geocode(){const q=$('[name="address"]')?.value;if(!q)throw new Error("請先填寫中文地址");if(!state.maptilerKey)throw new Error("尚未設定 MapTiler");const r=await fetch("https://api.maptiler.com/geocoding/"+encodeURIComponent(q+" 澳門")+".json?key="+encodeURIComponent(state.maptilerKey)+"&limit=1&country=mo"),d=await r.json(),c=d.features?.[0]?.center;if(!c)throw new Error("找不到地址");const [lng,lat]=c;$('[name="lat"]').value=lat.toFixed(6);$('[name="lng"]').value=lng.toFixed(6);pickerMarker.setLatLng([lat,lng]).addTo(pickerMap);pickerMap.setView([lat,lng],17)}
document.addEventListener("click",async e=>{const tab=e.target.closest("[data-tab]"),action=e.target.closest("[data-action]"),edit=e.target.closest("[data-edit]"),del=e.target.closest("[data-delete]"),move=e.target.closest("[data-move]"),remove=e.target.closest("[data-remove]"),removeCat=e.target.closest("[data-remove-cat]"),removeExp=e.target.closest("[data-remove-exp]"),clearImg=e.target.closest("[data-clear-image]"),submissionFilter=e.target.closest("[data-submission-filter]"),submissionAction=e.target.closest("[data-submission-status]");try{if(tab){closePicker();state.tab=tab.dataset.tab;state.edit=null;render()}else if(clearImg){const target=clearImg.dataset.clearImage;$('[name="'+target+'"]').value="";const prev=$('[data-preview="'+target+'"]');if(prev){prev.src="assets/macau-waterfront.png";prev.style.opacity="0.35"}toast("已清除圖片")}else if(removeCat){if((state.site.categories||[]).length<=1)return toast("至少需保留一個分類");state.site.categories.splice(Number(removeCat.dataset.removeCat),1);render()}else if(removeExp){state.site.experiences.splice(Number(removeExp.dataset.removeExp),1);render()}else if(submissionFilter){state.filters[state.tab==="reviews"?"reviews":"submissions"].status=submissionFilter.dataset.submissionFilter;render()}else if(submissionAction){const status=submissionAction.dataset.submissionStatus;await api("/api/admin/submissions/"+submissionAction.dataset.submissionId,{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({status})});await refresh();toast(status==="approved"?"投稿已採納":"投稿已標示為不採納")}else if(action){if(action.dataset.action==="add-cat"){state.site.categories=state.site.categories||[];state.site.categories.push({key:"去",titleZh:"新分類",titleEn:"New",subtitleZh:"探索澳門",subtitleEn:"Explore Macau",image:"assets/flat-waterfront.webp"});render()}if(action.dataset.action==="add-exp"){state.site.experiences=state.site.experiences||[];state.site.experiences.push({id:"exp-"+Date.now(),author:"@new_visitor",textZh:"在這裡寫下新的用戶體驗…",textEn:"Write a new experience…",image:""});render()}if(action.dataset.action==="new"){state.edit={};state.routeIds=[];render()}if(action.dataset.action==="cancel"){closePicker();state.edit=null;render()}if(action.dataset.action==="logout"){await api("/api/admin/logout",{method:"POST"});state.authed=false;render()}if(action.dataset.action==="geocode")await geocode()}else if(edit){state.edit=state.records[state.tab].find(x=>x.id===edit.dataset.edit);state.routeIds=[...(state.edit.ids||[])];render()}else if(del){const r=state.records[state.tab].find(x=>x.id===del.dataset.delete);if(confirm("確定刪除「"+recordName(r)+"」？")){await api("/api/admin/"+state.tab+"/"+r.id,{method:"DELETE"});await refresh();toast("已刪除")}}else if(move){const i=Number(move.dataset.move),j=i+Number(move.dataset.dir);if(j>=0&&j<state.routeIds.length)[state.routeIds[i],state.routeIds[j]]=[state.routeIds[j],state.routeIds[i]];$("#route-stops").innerHTML=routeStops()}else if(remove){state.routeIds.splice(Number(remove.dataset.remove),1);$("#route-stops").innerHTML=routeStops()}}catch(err){toast(err.message)}});
document.addEventListener("input",e=>{if(e.target.dataset.listFilter==="query"&&state.filters[state.tab]){state.filters[state.tab].query=e.target.value;render();const input=$("[data-list-filter=\"query\"]");input?.focus();input?.setSelectionRange(input.value.length,input.value.length)}});
document.addEventListener("change",async e=>{const listFilter=e.target.dataset.listFilter;if(listFilter&&listFilter!=="query"&&state.filters[state.tab]){state.filters[state.tab][listFilter]=e.target.value;render();return}if(e.target.id==="route-add"&&e.target.value){state.routeIds.push(e.target.value);$("#route-stops").innerHTML=routeStops();e.target.value=""}const target=e.target.dataset.upload;if(target&&e.target.files?.[0]){const file=e.target.files[0];if(file.size>5000000)return toast("圖片超過 5 MB");try{const d=await api("/api/upload",{method:"POST",headers:{"Content-Type":file.type},body:file});$('[name="'+target+'"]').value=d.url;const pv=$('[data-preview="'+target+'"]');if(pv){pv.src=d.url;pv.style.opacity="1"}toast("圖片已上傳")}catch(err){toast(err.message)}}});
document.addEventListener("submit",async e=>{e.preventDefault();if(e.target.id==="auth-form"){const f=new FormData(e.target),password=f.get("password");if(state.needsSetup&&password!==f.get("confirm"))return $("#auth-error").innerHTML='<div class="error">兩次密碼不一致。</div>';try{await api(state.needsSetup?"/api/admin/setup":"/api/admin/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({password})});state.authed=true;state.needsSetup=false;await refresh()}catch(err){$("#auth-error").innerHTML='<div class="error">'+esc(err.message)+"</div>"}}else if(e.target.id==="site-form"){const f=Object.fromEntries(new FormData(e.target)),site={...state.site};["heroTitleZh","heroTitleEn","heroBodyZh","heroBodyEn","heroImage","heroArticleId","searchPlaceholderZh","searchPlaceholderEn","catsTitleZh","catsTitleEn","catsBodyZh","catsBodyEn","routesTitleZh","routesTitleEn","routesBodyZh","routesBodyEn","expTitleZh","expTitleEn","expBodyZh","expBodyEn","featureTitleZh","featureTitleEn","featureImage","featureArticleId","aboutTitleZh","aboutTitleEn","aboutBodyZh","aboutBodyEn","aboutImage","contactEmail","contactWebsite","contactPhone","contactFax","contactAddressZh","contactAddressEn","footerTaglineZh","footerTaglineEn","footerNoteZh","footerNoteEn"].forEach(k=>{if(Object.hasOwn(f,k))site[k]=f[k]});site.hotSearchesZh=(f.hotSearchesZh||"").split(/[，,]/).map(x=>x.trim()).filter(Boolean);site.hotSearchesEn=(f.hotSearchesEn||"").split(",").map(x=>x.trim()).filter(Boolean);site.categories=(state.site.categories||[]).map((_,i)=>({key:f["categoryKey"+i],titleZh:f["categoryTitleZh"+i],titleEn:f["categoryTitleEn"+i],subtitleZh:f["categorySubZh"+i]||"",subtitleEn:f["categorySubEn"+i]||"",image:f["categoryImage"+i]}));site.experiences=(state.site.experiences||[]).map((x,i)=>({id:x.id||"exp-"+(i+1),author:f["expAuthor"+i]||"@visitor",textZh:f["expTextZh"+i]||"",textEn:f["expTextEn"+i]||"",image:f["expImage"+i]||""}));try{state.site=await api("/api/admin/site",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(site)});render();toast("全站設定已儲存")}catch(err){toast(err.message)}}else if(e.target.id==="record-form"){const f=new FormData(e.target),d=Object.fromEntries(f);if(state.tab==="places"){d.tags=f.getAll("tags");d.lat=d.lat===""?null:Number(d.lat);d.lng=d.lng===""?null:Number(d.lng)}if(state.tab==="routes")d.ids=state.routeIds;const creating=!state.edit.id;try{await api("/api/admin/"+state.tab+(creating?"":"/"+state.edit.id),{method:creating?"POST":"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(d)});closePicker();state.edit=null;await refresh();toast("內容已儲存")}catch(err){toast(err.message)}}});
init().catch(err=>app.innerHTML='<main class="login-shell"><div class="login-card"><h1>後台無法載入</h1><p>'+esc(err.message)+"</p></div></main>");
